INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l12','set out','',NULL,'/set aʊt/','Captain Reed will set out at eight o''clock.','里德船长将于八点启程。','We set out early to avoid the traffic.','我们早早出发,避开堵车。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l12','take part in','',NULL,'/teɪk pɑːrt ɪn/','He will take part in an important race.','他将参加一场重要的比赛。','Many students took part in the contest.','很多学生参加了这次比赛。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l12','be proud of','',NULL,'/bi praʊd əv/','We are all very proud of him.','我们都为他感到骄傲。','She is proud of her work.','她为自己的工作感到自豪。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp1','choice','{"stem":"一般将来时表示什么?","options":["将来要发生的事(will + 动词原形)","此刻正在做的事","过去发生的事","到现在为止的经历"],"answer_index":0,"explanation_cn":"一般将来时表示\"将来要发生、将来要做\"的事,用 will + 动词原形。✓ He will sail tomorrow.\r\n📌 表将来美语一律用 will;\"I shall / we shall\" 是英式或很正式的书面语,美语口语不用。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp1','choice','{"stem":"\"Captain Reed ___ tomorrow.\"(sail,一般将来)","options":["sails","sailed","is sailing","will sail"],"answer_index":3,"stem_cn":"里德船长明天将起航。","explanation_cn":"tomorrow(明天)是将来时间,用一般将来时 will + 动词原形 sail。✓ Captain Reed will sail tomorrow."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp1','choice','{"stem":"\"We ___ him at the dock.\"(meet,一般将来)","options":["will meet","meet","have met","met"],"answer_index":0,"stem_cn":"我们将去码头迎接他。","explanation_cn":"将来要做的事,用 will + 动词原形 meet。✓ We will meet him at the dock."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp2','choice','{"stem":"\"I will see you tomorrow.\" 口语缩略成:","options":["I willn''t see you tomorrow.","I''m see you tomorrow.","I see you tomorrow.","I''ll see you tomorrow."],"answer_index":3,"explanation_cn":"口语里 I will 常缩略成 I''ll。✓ I''ll see you tomorrow."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp2','choice','{"stem":"\"他会坐火车来\"的口语缩略说法:","options":["He''s come by train.","He''ll come by train.","He come by train.","He will to come by train."],"answer_index":1,"explanation_cn":"he will 口语缩略成 he''ll,后面接动词原形 come。✓ He''ll come by train."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp3','choice','{"stem":"\"He ___ away for two months.\"(将来的状态:不在)","options":["was","will","is","will be"],"answer_index":3,"stem_cn":"他将离开两个月。","explanation_cn":"\"离开(不在)\"是将来的状态,用 will be。✓ He will be away for two months."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp3','choice','{"stem":"\"We ___ at the dock early tomorrow.\"(将来在某地)","options":["were","are","will be","be"],"answer_index":2,"stem_cn":"明天一早我们就会在码头。","explanation_cn":"\"明天一早在码头\"是将来在某个地方,用 will be。✓ We will be at the dock early tomorrow."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp4','choice','{"stem":"\"她不会迟到\"的正确说法(will 否定):","options":["She doesn''t will be late.","She won''t be late.","She not will be late.","She will not to be late."],"answer_index":1,"explanation_cn":"一般将来时的否定 = won''t(will not)+ 动词原形。✓ She won''t be late."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp4','choice','{"stem":"\"他明天会走吗?\"(will 疑问):","options":["Will he leaves tomorrow?","He will leave tomorrow?","Does he will leave tomorrow?","Will he leave tomorrow?"],"answer_index":3,"explanation_cn":"一般将来时的疑问,把 will 提到句子最前面。✓ Will he leave tomorrow?"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp5','choice','{"stem":"把 \"I went to the party.\" 改成\"将要去\":","options":["I am go to the party.","I will go to the party.","I will went to the party.","I go to the party."],"answer_index":1,"explanation_cn":"\"将要去\"用一般将来时 will + 动词原形 go(不是过去式 went)。✓ I will go to the party."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp5','choice','{"stem":"下面哪一句表示\"将来要发生的事\"?","options":["The play is very successful now.","The play has been successful.","The play will be very successful.","The play was very successful."],"answer_index":2,"explanation_cn":"只有 will be 表示将来;was/is/has been 分别是过去、现在、到现在为止。✓ The play will be very successful."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp6','choice','{"stem":"be going to + 动词原形 表示什么?","options":["经常反复的习惯","过去正在做的事","已经做完的事","计划好、打算要做的事"],"answer_index":3,"explanation_cn":"be going to + 动词原形,表示计划好、打算要做的事,或有迹象很可能发生的事。✓ I am going to buy a car."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp6','choice','{"stem":"\"I ___ buy a new bike next week.\"(打算、计划好要做)","options":["will going to","go to","am going to","am go to"],"answer_index":2,"stem_cn":"我下周打算买辆新自行车。","explanation_cn":"\"打算下周买\"用 be going to;主语 I 用 am going to + 动词原形 buy。✓ I am going to buy a new bike next week."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp6','choice','{"stem":"\"Dark clouds are gathering. It ___ rain.\"(有迹象、马上要发生)","options":["will going to","is go to","goes to","is going to"],"answer_index":3,"stem_cn":"乌云正在聚集,快要下雨了。","explanation_cn":"\"乌云密布\"是\"要下雨\"的迹象,用 be going to;It 用 is going to。✓ It is going to rain."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp7','choice','{"stem":"\"The train ___ at 8:20.\"(时刻表，一般现在时表将来)","options":["leaves","is leave","leaved","will leaves"],"answer_index":0,"stem_cn":"火车8点20分发车。","explanation_cn":"时刻表上确定的班次,用一般现在时也能表将来。✓ The train leaves at 8:20."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp7','choice','{"stem":"\"We ___ a party this Friday.\"(已安排好，现在进行表将来)","options":["was having","have had","are having","will having"],"answer_index":2,"stem_cn":"这周五我们要办一场聚会。","explanation_cn":"已经安排好的事,可以用现在进行时表将来;We 用 are having。✓ We are having a party this Friday."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp8','choice','{"stem":"shall 在现代美语里主要用来做什么?","options":["提建议、征求意见(Shall we…? / Shall I…?)","表示过去发生的事","表示将来(美语这么用已过时,要用 will)","表示此刻正在做的事"],"answer_index":0,"explanation_cn":"shall 在现代美语里几乎只剩一个活用法:提建议、征求意见,用 Shall we…? / Shall I…?。✓ Shall we go? / Shall I open the window? 用它表将来(\"I shall go\")是英式/古旧说法,美语该用 will。\r\n📌 美国人提议说 \"Shall we…?\";表将来说 \"will\",不说 \"I shall\"。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',5,'am2_l12_gp8','choice','{"stem":"\"我们走吧?\"(提议一起做,注意人称和语序):","options":["Shall you go?","Will I go?","Do we shall go?","Shall we go?"],"answer_index":3,"explanation_cn":"提议\"我们…好吗?\"用 Shall we + 动词原形。✓ Shall we go? 这是 shall 在美语里最常见的活用法。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',6,NULL,'choice','{"stem":"美语\"港口\"的拼写是:","options":["harbur","harber","harbour","harbor"],"answer_index":3,"explanation_cn":"美语\"港口\"拼 harbor;英式拼 harbour。✓ sail from the harbor."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',6,NULL,'choice','{"stem":"美语\"邻居\"的拼写是:","options":["neighbor","neighour","neighbour","nieghbor"],"answer_index":0,"explanation_cn":"美语\"邻居\"拼 neighbor;英式拼 neighbour。✓ Our neighbor, Captain Reed."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',6,NULL,'choice','{"stem":"美语\"帆船\"常说:","options":["sailship","sailboat","boat sail","sailing boat"],"answer_index":1,"explanation_cn":"美语\"帆船\"常说 sailboat;英式说 sailing boat。✓ his little sailboat."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',6,NULL,'choice','{"stem":"set out 的意思是:","options":["返回","到达","停下","启程,出发"],"answer_index":3,"explanation_cn":"set out = 启程、动身出发。✓ He will set out at eight o''clock.\r\n顺带记:停下 = stop;返回 = return / go back;到达 = arrive / get to."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',6,NULL,'choice','{"stem":"take part in 的意思是:","options":["负责","参加","放弃","离开"],"answer_index":1,"explanation_cn":"take part in = 参加(活动/比赛)。✓ take part in a race.\r\n顺带记:离开 = leave;负责 = be in charge of;放弃 = give up."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',6,NULL,'choice','{"stem":"be proud of 的意思是:","options":["害怕…","担心…","厌倦…","为…感到自豪"],"answer_index":3,"explanation_cn":"be proud of = 为…感到自豪、骄傲。✓ We are proud of him.\r\n顺带记:害怕… = be afraid of;厌倦… = be tired of;担心… = be worried about."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',7,NULL,'cloze','{"stem":"第 1 空","context":"Captain Reed ___1___ from the harbor tomorrow. We ___2___ him at the dock early. He ___3___ away for two months. We are all very proud of him, and we ___4___ him win the race.","blank_no":1,"options":["will sail","sails","sailed","is sailing"],"answer_index":0,"explanation_cn":"tomorrow → 一般将来时 will sail。✓ Captain Reed will sail from the harbor tomorrow.\r\n✗ sails:tomorrow 是将来,不用一般现在 sails;✗ sailed:tomorrow 不是过去;✗ is sailing:这里陈述明天将起航这件将来的事,用 will,不用现在进行."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',7,NULL,'cloze','{"stem":"第 2 空","context":"Captain Reed ___1___ from the harbor tomorrow. We ___2___ him at the dock early. He ___3___ away for two months. We are all very proud of him, and we ___4___ him win the race.","blank_no":2,"options":["will meet","meet","met","are meeting"],"answer_index":0,"explanation_cn":"将来要做的事 → will meet。✓ We will meet him at the dock early.\r\n✗ meet:将来的事不用一般现在 meet;✗ met:不是过去发生的;✗ are meeting:此处是泛说将来的送行安排,用 will 更贴切."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',7,NULL,'cloze','{"stem":"第 3 空","context":"Captain Reed ___1___ from the harbor tomorrow. We ___2___ him at the dock early. He ___3___ away for two months. We are all very proud of him, and we ___4___ him win the race.","blank_no":3,"options":["will be","is","was","be"],"answer_index":0,"explanation_cn":"将来的状态(不在) → will be。✓ He will be away for two months.\r\n✗ is:将来的状态不用现在 is;✗ was:不是过去;✗ be:be 不能单独作谓语,前面缺 will."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',7,NULL,'cloze','{"stem":"第 4 空","context":"Captain Reed ___1___ from the harbor tomorrow. We ___2___ him at the dock early. He ___3___ away for two months. We are all very proud of him, and we ___4___ him win the race.","blank_no":4,"options":["will watch","watch","watched","have watched"],"answer_index":0,"explanation_cn":"将来要做的事 → will watch。✓ We will watch him win the race.\r\n✗ watch:将来的事不用一般现在 watch;✗ watched:不是过去;✗ have watched:现在完成表\"已经看过\",与\"将要看\"矛盾."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',8,NULL,'choice','{"stem":"When will Captain Reed set out?","options":["At eight o''clock","In the evening","At noon","At nine o''clock"],"answer_index":0,"explanation_cn":"课文说 Captain Reed will set out at eight o''clock sharp,船长八点整启程。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',8,NULL,'choice','{"stem":"How long will he be away?","options":["Two days","About two months","Two years","Two weeks"],"answer_index":1,"explanation_cn":"课文说 He is going to be away for about two months,他将离开大约两个月。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',8,NULL,'choice','{"stem":"What will Captain Reed take part in?","options":["A concert","A fishing trip","A boat show","A race across the ocean"],"answer_index":3,"explanation_cn":"课文说 He will take part in an important race across the ocean,他要参加横渡大洋的比赛。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',9,NULL,'choice','{"stem":"你想说\"明天我会给你打电话\"(将来要做，一般将来时):","options":["I am call you tomorrow.","I will call you tomorrow.","I call you tomorrow.","I called you tomorrow."],"answer_index":1,"explanation_cn":"\"明天会打电话\"是将来要做的事,用一般将来时 will call。✓ I will call you tomorrow. 场合:答应别人明天联系。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',9,NULL,'choice','{"stem":"你想说\"我打算这个周末去爬山\"(计划好要做的事):","options":["I climbed the mountain this weekend.","I climb the mountain this weekend.","I will going to climb this weekend.","I am going to climb the mountain this weekend."],"answer_index":3,"explanation_cn":"\"打算这周末去爬山\"是计划好的事,用 be going to。✓ 场合:说自己的周末安排。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',9,NULL,'choice','{"stem":"你想提议\"我们一起吃午饭好吗?\"(提议一起做某事):","options":["Shall we have lunch together?","We shall having lunch?","Will I have lunch together?","Do we shall have lunch?"],"answer_index":0,"explanation_cn":"提议\"我们一起…好吗?\"用 Shall we + 动词原形。✓ Shall we have lunch together? 场合:约朋友吃饭。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',10,NULL,'choice','{"stem":"captain 的意思是:","options":["渔民","乘客","水手","船长"],"answer_index":3,"explanation_cn":"captain = 船长(也可指队长)。✓ Captain David Reed.\r\n顺带记:水手 = sailor;乘客 = passenger;渔民 = fisherman."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',10,NULL,'choice','{"stem":"proud 的意思是:","options":["伤心的","疲倦的","自豪的","害怕的"],"answer_index":2,"explanation_cn":"proud = 自豪的、骄傲的。✓ We are proud of him.\r\n顺带记:害怕的 = afraid / scared;伤心的 = sad;疲倦的 = tired."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',10,NULL,'choice','{"stem":"\"They ___ here on foot tomorrow.\"(come,一般将来)","options":["come","came","have come","will come"],"answer_index":3,"stem_cn":"他们明天会步行来这儿。","explanation_cn":"tomorrow → 一般将来时 will + 动词原形 come。✓ They will come here on foot tomorrow."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',10,NULL,'choice','{"stem":"\"Look at those clouds! It ___ snow.\"(有迹象、马上要发生)","options":["goes to","snowed","is going to","will going to"],"answer_index":2,"stem_cn":"看那些云!要下雪了。","explanation_cn":"\"看那些云!\"是\"要下雪\"的迹象,用 be going to;It 用 is going to。✓ It is going to snow."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',10,NULL,'choice','{"stem":"\"我们几点出发?\"(询问将来的安排,用 shall):","options":["What time shall we set out?","What time set out we?","What time did we set out?","What time we shall set out?"],"answer_index":0,"explanation_cn":"问将来的安排\"我们几点出发\",用 What time shall we + 动词原形。✓ What time shall we set out?"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',10,NULL,'choice','{"stem":"\"I''ll be back at six.\" 的意思是:","options":["我六点正在回来的路上","我六点前一直不在","我六点会回来","我六点已经回来了"],"answer_index":2,"explanation_cn":"I''ll be back at six = 我六点会回来(''ll 是 will 的缩略,表将来)。✓"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',10,NULL,'choice','{"stem":"How will the writer''s group say goodbye to the captain?","options":["They will sail across the ocean with him","They will watch his boat leave and shout ''Good luck!''","They will send him a letter","They will call him on the phone"],"answer_index":1,"passage":"Our neighbor, Captain David Reed, will sail from the harbor tomorrow morning. We are going to meet him at the dock bright and early. He will be on his little sailboat, the Seabird. The Seabird is a famous little boat, and it has crossed the Atlantic many times. Captain Reed will set out at eight o''clock sharp, so we''ll have plenty of time. We''ll watch his boat leave, and then we''ll say goodbye to him. \"Good luck!\" we will all shout from the dock. He is going to be away for about two months. We are all very proud of him. He will take part in an important race across the ocean. I think he will win, and we will welcome him home like a hero.","explanation_cn":"课文说他们会目送船离开、在码头喊\"Good luck!\",这就是他们的道别方式。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',10,NULL,'choice','{"stem":"Why is everyone proud of Captain Reed?","options":["He will take part in an important ocean race","He just bought a new house","He is very rich","He won a prize last year"],"answer_index":0,"passage":"Our neighbor, Captain David Reed, will sail from the harbor tomorrow morning. We are going to meet him at the dock bright and early. He will be on his little sailboat, the Seabird. The Seabird is a famous little boat, and it has crossed the Atlantic many times. Captain Reed will set out at eight o''clock sharp, so we''ll have plenty of time. We''ll watch his boat leave, and then we''ll say goodbye to him. \"Good luck!\" we will all shout from the dock. He is going to be away for about two months. We are all very proud of him. He will take part in an important race across the ocean. I think he will win, and we will welcome him home like a hero.","explanation_cn":"课文说 He will take part in an important race across the ocean,大家为他参加横渡大洋的比赛而自豪。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',10,NULL,'choice','{"stem":"What is the name of the captain''s boat?","options":["The Portsmouth","The Atlantic","The Seabird","The Topsail"],"answer_index":2,"audio":"Our neighbor, Captain David Reed, will sail from the harbor tomorrow morning. We are going to meet him at the dock bright and early. He will be on his little sailboat, the Seabird. The Seabird is a famous little boat, and it has crossed the Atlantic many times. Captain Reed will set out at eight o''clock sharp, so we''ll have plenty of time. We''ll watch his boat leave, and then we''ll say goodbye to him. \"Good luck!\" we will all shout from the dock. He is going to be away for about two months. We are all very proud of him. He will take part in an important race across the ocean. I think he will win, and we will welcome him home like a hero.","explanation_cn":"课文说 He will be on his little sailboat, the Seabird,船名叫\"海鸟号\"。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l12',10,NULL,'choice','{"stem":"Where will they meet the captain?","options":["At his house","At the dock by the harbor","At the airport","At the school"],"answer_index":1,"audio":"Our neighbor, Captain David Reed, will sail from the harbor tomorrow morning. We are going to meet him at the dock bright and early. He will be on his little sailboat, the Seabird. The Seabird is a famous little boat, and it has crossed the Atlantic many times. Captain Reed will set out at eight o''clock sharp, so we''ll have plenty of time. We''ll watch his boat leave, and then we''ll say goodbye to him. \"Good luck!\" we will all shout from the dock. He is going to be away for about two months. We are all very proud of him. He will take part in an important race across the ocean. I think he will win, and we will welcome him home like a hero.","explanation_cn":"课文说 We are going to meet him at the dock,他们在港口的码头为船长送行。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l13',2,2,13,'The Greenwood Boys','绿林少年(流行歌手团)','将来进行时(主考:will/shall be + V-ing · 现在进行 vs 将来进行 · 各人称 · 疑问Will you be doing…? · ≈一般将来时 · 表安排好的将来)+ by+交通工具(辅考)+ 现在进行时复习对照(辅考)','流行歌手团明天乘火车到镇上 · 粉丝去车站接、晚上俱乐部演出、待五天 · 警察照例忙着维持秩序','{"q":"Listen and answer — Why will the police have a difficult time?","options":["Huge crowds of fans will gather for the band","The band is dangerous","The station is closed","There is a storm coming"],"answer_index":0}'::jsonb,'{"title":"说\"将来某时正在做什么\"(将来进行时)","intro":"本课讲怎么说\"将来某个时候正在做某事\"——将来进行时。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["将来进行时 = will/shall be + 动词-ing(将来某时正在进行)","They will be arriving tomorrow.(明天将要到达)"],["现在''正在''用 am/is/are + doing;将来''正在''用 will be + doing","现在:They are playing. 明天:They will be playing tomorrow."],["各人称都用 will be(第一人称也可用 shall be);口语 ''ll be","I''ll be seeing you. / He''ll be coming by train."],["疑问:把 will 提前(Will you be doing…?);否定:won''t be + doing","Will you be washing your car tomorrow?"],["将来进行时和一般将来时常可互换,都表将来","He''ll arrive soon. = He''ll be arriving soon."]]},"specialRules":[{"rule":"将来进行时常表示''已经安排好的、最近就要发生''的事(will be arriving = 快到了)","mark":"安排好的将来"},{"rule":"乘坐交通工具用 by:by train / by air / by sea / by bus(名词前不加 the/a)","mark":"by + 交通工具"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l13',1,NULL,'The Silver Hawks are a group of pop singers.','"银鹰"是一个流行歌手组合。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l13',2,NULL,'At present, they are traveling all across the country.','目前,他们正在全国各地巡演。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l13',3,NULL,'They will be arriving in our town tomorrow.','他们明天就要到我们镇上了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l13',4,NULL,'They will be coming by train, and most of the young fans will be meeting them at the station.','他们将乘火车来,镇上大多数年轻粉丝都会去车站迎接他们。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l13',5,NULL,'Tomorrow evening, they will be singing downtown at the Community Club.','明天晚上,他们将在市中心的社区俱乐部演出。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l13',6,NULL,'The Silver Hawks will be staying for five days, and they will give five performances.','"银鹰"将逗留五天,一共演出五场。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l13',7,NULL,'Hundreds of fans will be lining up outside the club for hours.','成百上千的粉丝会在俱乐部外排队等上好几个小时。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l13',8,NULL,'As usual, the police will have a difficult time.','和往常一样,警察的日子会不好过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l13',9,NULL,'They will be trying hard to keep order.','他们将竭力维持秩序。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l13',10,NULL,'It is always the same on these big occasions.','每逢这种大场合,情况总是这样。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l13',11,NULL,'What will you be doing when the Silver Hawks arrive?','"银鹰"来的时候,你会在做什么呢?') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
