INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l14','trip','journey','旅程;美语常说 trip,英式常说 journey(课文保留 journey 教官方词)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
