INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l14','on the way','',NULL,'/ɑːn ðə weɪ/','On the way, a young man waved at me.','途中,一个青年向我招手。','I bought some coffee on the way to work.','上班途中我买了点咖啡。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l14','ask for a lift','',NULL,'/æsk fər ə lɪft/','He asked me for a lift.','他请求搭我的便车。','She asked her neighbor for a lift to the airport.','她请邻居捎她去机场。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l14','apart from','',NULL,'/əˈpɑːrt frəm/','Apart from a few words, I did not know any French.','除了几个单词,我根本不会法语。','Apart from Tom, everyone came.','除了汤姆,大家都来了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp1','choice','{"stem":"过去完成时由什么构成?","options":["have + 过去分词","had + 过去分词","will + 动词原形","was + 过去分词"],"answer_index":1,"explanation_cn":"过去完成时 = had + 过去分词,表示\"过去的过去\"(比某个过去时间更早发生)。✓ After I had left the village…"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp1','choice','{"stem":"\"After I ___ the village, I drove on.\"(leave,先离开，过去完成)","options":["had left","left","was leaving","have left"],"answer_index":0,"stem_cn":"我离开村庄后,继续往前开。","explanation_cn":"\"离开村庄\"发生在\"开车走\"之前,先发生的用过去完成时 had left。✓ After I had left the village, I drove on."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp1','choice','{"stem":"\"When he ___ lunch, he asked for water.\"(finish,先吃完，过去完成)","options":["finished","finishes","has finished","had finished"],"answer_index":3,"stem_cn":"他吃完午饭后,要了些水。","explanation_cn":"\"吃完午饭\"在\"要水\"之前,先发生的用过去完成时 had finished。✓ When he had finished lunch, he asked for water."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp2','choice','{"stem":"过去完成时用来表示什么?","options":["将来要做的事","过去两个动作里,先发生的那个","此刻正在做的事","经常反复的习惯"],"answer_index":1,"explanation_cn":"过去完成时用来表示过去的两个动作里,哪一个更早发生(先发生的用过去完成)。✓"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp2','choice','{"stem":"\"As soon as he had gotten into the car, I said hi.\" 哪件事先发生?","options":["他上车(had gotten in)","我打招呼(said hi)","两件同时","都没发生"],"answer_index":0,"explanation_cn":"had gotten in 是过去完成时,表示更早发生;said hi 是一般过去时,后发生。所以先发生的是\"上车\"。✓"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp3','choice','{"stem":"\"The children ran away ___ they had broken the window.\"(在…之后)","options":["before","after","so","and"],"answer_index":1,"stem_cn":"孩子们打碎窗户之后就跑掉了。","explanation_cn":"\"孩子们打碎玻璃之后跑了\"——\"在…之后\"用 after,后接过去完成时 had broken。✓ ran away after they had broken the window."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp3','choice','{"stem":"\"___ the sun had set, we returned to the hotel.\"(太阳一下山就…)","options":["Because","Although","Unless","As soon as"],"answer_index":3,"stem_cn":"太阳一下山,我们就回了旅馆。","explanation_cn":"\"太阳一下山我们就回旅馆\"——\"一…就…\"用 As soon as,后接过去完成时 had set。✓ As soon as the sun had set, we returned."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp3','choice','{"stem":"\"She went to the post office ___ she had written the letter.\"(先写完信)","options":["but","until","after","or"],"answer_index":2,"stem_cn":"她写完信后去了邮局。","explanation_cn":"\"写完信之后去邮局\"——先写完(had written)后去,用 after 引导。✓ She went to the post office after she had written the letter."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp4','choice','{"stem":"\"I ___ the problem until he explained it.\"(否定 + until,过去完成)","options":["did not understand","was not understanding","have not understood","had not understood"],"answer_index":3,"stem_cn":"直到他解释,我才弄懂这个问题。","explanation_cn":"过去完成时否定 = had not + 过去分词,常和 until 连用(直到…才…)。✓ I had not understood the problem until he explained it."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp5','choice','{"stem":"关于一般过去时和过去完成时,正确的是:","options":["一般过去时表此刻正在","两个时态完全一样","相继发生按顺序讲用一般过去;回头看更早的用过去完成","过去完成时表将来"],"answer_index":2,"explanation_cn":"两件相继发生、按先后顺序讲的事,用一般过去时;过去完成时是\"回头看\"更早发生的那件。✓"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp5','choice','{"stem":"\"He arrived and (then) sat down.\" 两件相继发生、按顺序讲,用:","options":["过去完成(had arrived, had sat)","一般过去(arrived, sat)","将来时","现在完成"],"answer_index":1,"explanation_cn":"\"到了然后坐下\"是相继发生、按顺序讲的两件事,都用一般过去时 arrived, sat,不用过去完成时。✓"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp5','choice','{"stem":"\"When I got to the station, the train ___ already ___.\"(我到之前车已开走，过去完成)","options":["did … leave","was … leaving","had … left","has … left"],"answer_index":2,"stem_cn":"我到车站时,火车已经开走了。","explanation_cn":"\"我到车站之前,火车已经开走了\"——开走在\"到\"之前,用过去完成时 had already left。✓ When I got to the station, the train had already left."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp6','choice','{"stem":"\"I ___ to go shopping, but my mom came.\"(本打算…但没成)","options":["had planned","am planning","will plan","plan"],"answer_index":0,"stem_cn":"我本打算去购物,但我妈妈来了。","explanation_cn":"\"本打算去购物,但妈妈来了(没去成)\"——本打算而未实现,用 had planned to。✓ I had planned to go shopping, but my mom came."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp6','choice','{"stem":"\"She ___ that he would come, but he didn''t.\"(原本希望…但落空)","options":["hopes","will hope","is hoping","had hoped"],"answer_index":3,"stem_cn":"她原本希望他会来,但他没来。","explanation_cn":"\"原本希望他来,但他没来\"——原本希望而落空,用 had hoped that。✓ She had hoped that he would come, but he didn''t."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp7','choice','{"stem":"\"It was the third time that I ___ him.\"(正式/书面:此句式规范用过去完成)","options":["have met","meet","had met","meeting"],"answer_index":2,"stem_cn":"那是我第三次见他。","explanation_cn":"\"这是我第三次见他\"用 \"It was the … time that + 过去完成时\" 句式,填 had met。✓ It was the third time that I had met him.\r\n📌 口语里美国人也常说 \"It was the third time I met him\"(裸过去);考试和正式写作用 \"had met\"。两种都对,场合不同。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp8','choice','{"stem":"过去完成时的否定是:","options":["was not + 过去分词","did not + 过去分词","have not + 过去分词","had not + 过去分词"],"answer_index":3,"explanation_cn":"过去完成时的否定 = had not + 过去分词。✓ I had not seen him before."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp8','choice','{"stem":"\"___ you ever seen him before that day?\"(过去完成疑问)","options":["Were","Had","Did","Have"],"answer_index":1,"stem_cn":"那天之前你见过他吗?","explanation_cn":"过去完成时的疑问,把 had 提到句子最前面。✓ Had you ever seen him before that day?"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp8','choice','{"stem":"\"By six o''clock, they ___ dinner.\"(到六点之前已吃完，过去完成)","options":["have finished","finished","had finished","finish"],"answer_index":2,"stem_cn":"到六点时,他们已经吃完晚饭了。","explanation_cn":"\"到六点之前他们已吃完饭\"——吃完在\"六点\"之前,用过去完成时 had finished。✓ By six o''clock, they had finished dinner."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp9','choice','{"stem":"\"他自己\"的反身代词是:","options":["himself","hisself","heself","him self"],"answer_index":0,"explanation_cn":"\"他自己\"的反身代词是 himself(没有 hisself 这种拼法)。反身代词:myself/yourself/himself/herself/itself/ourselves/yourselves/themselves。✓"}'::jsonb,19) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp9','choice','{"stem":"\"God helps those who help ___.\"(动作回到自己身上,用反身代词)","options":["them","themselves","theirs","they"],"answer_index":1,"stem_cn":"天助自助者(上天帮助自己帮自己的人)。","explanation_cn":"当动作又回到做这个动作的人身上时,用反身代词;those(那些人)对应 themselves。✓ God helps those who help themselves.(天助自助者)"}'::jsonb,20) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',5,'am2_l14_gp9','choice','{"stem":"\"The young man was English ___.\"(强调\"他本人就是\",课文原句)","options":["he","his","himself","him"],"answer_index":2,"stem_cn":"那青年本人就是英国人。","explanation_cn":"反身代词还能放在名词后面起强调作用,强调\"他本人就是\"。✓ The young man was English himself.(那青年本人就是英国人 —— 课文原句)"}'::jsonb,21) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',6,NULL,'choice','{"stem":"美语里\"搭便车\"更常说:","options":["ride","lift","hitch stop","car help"],"answer_index":0,"explanation_cn":"美语里\"搭便车\"更常说 ride(give sb a ride);英式说 lift。✓ Can you give me a ride?"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',6,NULL,'choice','{"stem":"美语里\"旅程/旅行\"更常说:","options":["way go","journey","trip","voyage road"],"answer_index":2,"explanation_cn":"美语里\"旅程/旅行\"更常说 trip;英式常说 journey。✓ a road trip."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',6,NULL,'choice','{"stem":"美语里\"假期\"用:","options":["offtime","vacation","restday","holiday"],"answer_index":1,"explanation_cn":"美语\"假期\"用 vacation;英式用 holiday。✓ on vacation in France."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',6,NULL,'choice','{"stem":"on the way 的意思是:","options":["在途中","迷路了","在起点","在路边"],"answer_index":0,"explanation_cn":"on the way = 在途中、在路上。✓ On the way, a young man waved.\r\n顺带记:在路边 = by the roadside;迷路了 = get lost / lose one''s way;在起点 = at the start."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',6,NULL,'choice','{"stem":"ask for a lift 的意思是:","options":["问路","要求搭便车","请求帮忙提东西","要一杯水"],"answer_index":1,"explanation_cn":"ask for a lift = 要求搭便车。✓ He asked me for a lift.\r\n顺带记:问路 = ask the way / ask for directions;要一杯水 = ask for a glass of water;请求帮忙提东西 = ask for help carrying sth."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',6,NULL,'choice','{"stem":"apart from 的意思是:","options":["除了…以外","关于","紧挨着","属于"],"answer_index":0,"explanation_cn":"apart from = 除了…以外。✓ Apart from a few words, I did not know any French.\r\n顺带记:紧挨着 = next to / close to;属于 = belong to;关于 = about."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',7,NULL,'cloze','{"stem":"第 1 空","context":"After I ___1___ the village, I ___2___ on toward the next town. A young man asked me for a lift. As soon as he ___3___ into the car, I said hi in French. I ___4___ nearly reached the town when he asked, \"Do you speak English?\"","blank_no":1,"options":["had left","leave","have left","was leaving"],"answer_index":0,"explanation_cn":"\"离开村庄\"先发生,用过去完成时 had left。✓ After I had left the village…\r\n✗ leave:过去的事不用动词原形;✗ have left:现在完成表到现在,这是\"过去的过去\"要用 had;✗ was leaving:过去进行不表\"更早已完成\"."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',7,NULL,'cloze','{"stem":"第 2 空","context":"After I ___1___ the village, I ___2___ on toward the next town. A young man asked me for a lift. As soon as he ___3___ into the car, I said hi in French. I ___4___ nearly reached the town when he asked, \"Do you speak English?\"","blank_no":2,"options":["drove","had driven","drive","was driven"],"answer_index":0,"explanation_cn":"\"继续开车\"后发生,用一般过去时 drove。✓ I drove on toward the next town.\r\n✗ had driven:开车是后发生的动作,用一般过去 drove,不用过去完成;✗ drive:过去的事不用原形;✗ was driven:被动语态,意思变成\"被开走\"了."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',7,NULL,'cloze','{"stem":"第 3 空","context":"After I ___1___ the village, I ___2___ on toward the next town. A young man asked me for a lift. As soon as he ___3___ into the car, I said hi in French. I ___4___ nearly reached the town when he asked, \"Do you speak English?\"","blank_no":3,"options":["had gotten","got","has gotten","gets"],"answer_index":0,"explanation_cn":"\"上车\"先于\"打招呼\",用过去完成时 had gotten。✓ As soon as he had gotten into the car…\r\n✗ got:这里强调\"一上车(更早)就…\",用过去完成 had gotten;✗ has gotten:现在完成表到现在,不用于过去的过去;✗ gets:一般现在时,过去的事不用."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',7,NULL,'cloze','{"stem":"第 4 空","context":"After I ___1___ the village, I ___2___ on toward the next town. A young man asked me for a lift. As soon as he ___3___ into the car, I said hi in French. I ___4___ nearly reached the town when he asked, \"Do you speak English?\"","blank_no":4,"options":["had","have","was","did"],"answer_index":0,"explanation_cn":"\"快到镇上\"是更早的背景,用过去完成时 had reached。✓ I had nearly reached the town when…\r\n✗ have:过去的背景用 had reached,不用 have;✗ was:was reached 成了被动,意思错;✗ did:助动词 did 不与过去分词 reached 搭配."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',8,NULL,'choice','{"stem":"Where did the writer pick up the young man?","options":["On the way to the next town","At the airport","At a gas station","In the town center"],"answer_index":0,"explanation_cn":"课文说 On the way, a young man waved at me,作者在去下个镇的途中搭上他。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',8,NULL,'choice','{"stem":"Did they talk during the journey?","options":["Yes, in English","Only the driver spoke","No, neither of them spoke","Yes, they talked a lot"],"answer_index":2,"explanation_cn":"课文说 Neither of us spoke during the whole journey,一路上谁也没说话。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',8,NULL,'choice','{"stem":"What nationality was the young man?","options":["American","German","French","English"],"answer_index":3,"explanation_cn":"课文结尾说 the young man was English himself,那青年其实是英国人。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',9,NULL,'choice','{"stem":"你想说\"我到车站时,火车已经开走了\"(到之前已开走，过去完成):","options":["When I got to the station, the train had already left.","When I got to the station, the train has left.","When I got to the station, the train was leaving now.","When I got to the station, the train leaves."],"answer_index":0,"explanation_cn":"\"火车开走\"在\"我到\"之前,先发生的用过去完成时 had already left。✓ 场合:解释自己为什么没赶上车。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',9,NULL,'choice','{"stem":"你想说\"她写完作业后就睡了\"(先写完，after…had done):","options":["After she has finished her homework, she went to bed.","After she finishes her homework, she went to bed.","After she had finished her homework, she went to bed.","After she will finish her homework, she went to bed."],"answer_index":2,"explanation_cn":"\"写完作业\"先发生,用 after + 过去完成时 had finished;\"睡觉\"后发生用一般过去 went。✓"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',9,NULL,'choice','{"stem":"你想说\"我本打算去看你,但太忙了\"(本打算但没成):","options":["I plan to visit you, but I was too busy.","I have planned to visit you, but I was too busy.","I will plan to visit you, but I was too busy.","I had planned to visit you, but I was too busy."],"answer_index":3,"explanation_cn":"\"本打算去看你但没成\"用 had planned to,表示过去未实现的计划。✓ 场合:向朋友解释爽约。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"amusing 的意思是:","options":["危险的","无聊的","有趣的,好笑的","重要的"],"answer_index":2,"explanation_cn":"amusing = 有趣的、好笑的。✓ an amusing experience.\r\n顺带记:无聊的 = boring;危险的 = dangerous;重要的 = important."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"journey 的意思是:","options":["旅程,旅行","村庄","工作","语言"],"answer_index":0,"explanation_cn":"journey = 旅程、旅行。✓ during the whole journey.\r\n顺带记:工作 = job / work;语言 = language;村庄 = village."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"\"He told me that he ___ the book before.\"(read,更早读过，过去完成)","options":["reads","had read","will read","has read"],"answer_index":1,"stem_cn":"他告诉我他以前读过这本书。","explanation_cn":"\"他更早读过这本书\"(在告诉我之前),用过去完成时 had read。✓ He told me that he had read the book before."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"\"By the time we arrived, the movie ___.\"(我们到之前已开始，过去完成)","options":["was starting now","has started","starts","had started"],"answer_index":3,"stem_cn":"我们到的时候,电影已经开始了。","explanation_cn":"\"我们到之前电影已经开始\"——开始在\"到\"之前,用过去完成时 had started。✓ By the time we arrived, the movie had started."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"\"After he had eaten, he washed the dishes.\" 哪件事先发生?","options":["他洗碗(washed)","他吃饭(had eaten)","两件同时","都没发生"],"answer_index":1,"explanation_cn":"had eaten 是过去完成时,更早发生;washed 是一般过去时,后发生。所以先发生的是\"吃饭\"。✓"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"\"我本想给你打电话,可手机没电了\"(本打算但没成)用:","options":["had planned to call","am calling","will call","plan to call"],"answer_index":0,"explanation_cn":"\"本想打电话,可手机没电了(没打成)\"用 had planned to call,表示过去未实现的打算。✓"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"Why did the writer speak French to the young man?","options":["The young man asked him to","He wanted to practice French","He thought the young man was a local Frenchman","It was the law in France"],"answer_index":2,"passage":"I had an amusing experience last summer while I was on vacation in France. After I had left a small village in the south of France, I drove on toward the next town. On the way, a young man waved at me and asked me for a lift. As soon as he had gotten into the car, I said good morning to him in French. He replied in the same language, so I figured he was a local Frenchman. Apart from a few words, I did not know any French at all. Neither of us spoke during the whole journey. I had nearly reached the town when the young man suddenly turned to me. Very slowly, he asked, \"Do you speak English?\" I was surprised, because before he spoke, I had thought he was French. As I soon learned, the young man was English himself!","explanation_cn":"课文说作者以为那青年是本地法国人,所以用法语跟他说话。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"What surprised the writer at the end?","options":["The young man was actually English","The car broke down","The young man could not speak","The town was closed"],"answer_index":0,"passage":"I had an amusing experience last summer while I was on vacation in France. After I had left a small village in the south of France, I drove on toward the next town. On the way, a young man waved at me and asked me for a lift. As soon as he had gotten into the car, I said good morning to him in French. He replied in the same language, so I figured he was a local Frenchman. Apart from a few words, I did not know any French at all. Neither of us spoke during the whole journey. I had nearly reached the town when the young man suddenly turned to me. Very slowly, he asked, \"Do you speak English?\" I was surprised, because before he spoke, I had thought he was French. As I soon learned, the young man was English himself!","explanation_cn":"课文结尾揭示那青年其实是英国人,这让作者很吃惊。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"How did the young man get the writer''s attention?","options":["He blocked the road","He called his phone","He shouted from a window","He waved at him on the way"],"answer_index":3,"audio":"I had an amusing experience last summer while I was on vacation in France. After I had left a small village in the south of France, I drove on toward the next town. On the way, a young man waved at me and asked me for a lift. As soon as he had gotten into the car, I said good morning to him in French. He replied in the same language, so I figured he was a local Frenchman. Apart from a few words, I did not know any French at all. Neither of us spoke during the whole journey. I had nearly reached the town when the young man suddenly turned to me. Very slowly, he asked, \"Do you speak English?\" I was surprised, because before he spoke, I had thought he was French. As I soon learned, the young man was English himself!","explanation_cn":"课文说 On the way, a young man waved at me,青年在途中招手拦车。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l14',10,NULL,'choice','{"stem":"When did the young man ask \"Do you speak English?\"","options":["Near the end, close to the town","At the gas station","Right when he got in the car","Before the trip started"],"answer_index":0,"audio":"I had an amusing experience last summer while I was on vacation in France. After I had left a small village in the south of France, I drove on toward the next town. On the way, a young man waved at me and asked me for a lift. As soon as he had gotten into the car, I said good morning to him in French. He replied in the same language, so I figured he was a local Frenchman. Apart from a few words, I did not know any French at all. Neither of us spoke during the whole journey. I had nearly reached the town when the young man suddenly turned to me. Very slowly, he asked, \"Do you speak English?\" I was surprised, because before he spoke, I had thought he was French. As I soon learned, the young man was English himself!","explanation_cn":"课文说 I had nearly reached the town when the young man suddenly asked,快到镇上时他才问。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l15',2,2,15,'Good news','佳音','间接引语(主考:say/tell + that + 从句 · say 不接人 tell 接人 · 时态后移 am→was/will→would/can→could/have done→had done · 人称变化 · 转述疑问 asked if/whether)+ 宾语从句 that可省/if vs whether(辅考讲深)+ 过去将来时 would/should(辅考讲深)','被老板叫进办公室 · 紧张以为要被裁员 · 老板说生意差、公司付不起工资、已裁二十人 · 正准备挨刀时却反被告知加薪一千','{"q":"Listen and answer — What was the good news?","options":["The writer would get a raise, not get fired","The firm was closing down","The writer was fired","Business was good again"],"answer_index":0}'::jsonb,'{"title":"转述别人的话(间接引语)","intro":"本课讲怎么把别人说的话''转述''出来——间接引语。转述过去说过的话时,从句里的时态要往过去''退一步''。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["间接引语:say / tell + that + 从句(that 常可省)","He said that business was bad."],["say 后不接人;tell 后必须接人","He said that… / He told me that…"],["转述过去说的话,从句时态往过去退:am→was, do→did","''I am busy.'' → He said that he was busy."],["will→would;can→could;have done→had done","''I will see you.'' → She said she would see me."],["人称跟着变:I→he/she, my→his/her","''I broke it.'' → He said that he had broken it."]]},"specialRules":[{"rule":"转述一般疑问句用 ask if/whether + 陈述语序(不再倒装、不加问号)","mark":"转述疑问"},{"rule":"从过去看将来,will 变 would(过去将来时);would 通用于各人称","mark":"will→would"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l15',1,NULL,'The secretary told me that Mr. Harrison would see me right away.','秘书告诉我,哈里森先生马上就要见我。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l15',2,NULL,'I felt very nervous as I took the elevator up to his office.','我乘电梯上楼去他办公室时,感到非常紧张。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l15',3,NULL,'He did not even look up from his desk when I walked in.','我走进去时,他连头都没从桌上抬一下。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l15',4,NULL,'After I had sat down, he said that business was very bad.','等我坐下后,他说生意非常不景气。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l15',5,NULL,'He told me that the firm could not afford to pay such high salaries.','他告诉我,公司付不起这么高的工资。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l15',6,NULL,'Twenty people had already been let go, and I knew that my turn had come.','已经有二十个人被辞退了,我知道这回该轮到我了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l15',7,NULL,'"Mr. Harrison," I said in a weak voice, "may I say something?"','"哈里森先生,"我用微弱的声音说,"我能说句话吗?"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l15',8,NULL,'"Don''t interrupt me," he said sharply.','"别打断我,"他厉声说道。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l15',9,NULL,'Then he suddenly smiled and told me that I would get a raise.','接着他突然笑了,告诉我我要加薪了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l15',10,NULL,'He said I would receive an extra thousand dollars a year.','他说我每年将多拿一千美元。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l15',11,NULL,'It was the best news I had heard all year!','这是我一整年里听到的最好的消息!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
