INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp1','choice','{"stem":"间接引语是用来做什么的?","options":["描述正在发生的事","问别人问题","转述别人说过的话","命令别人做事"],"answer_index":2,"explanation_cn":"间接引语就是把别人说过的话\"转述\"出来(不加引号,不照搬原话)。✓ He said that business was bad."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp1','choice','{"stem":"间接引语常用哪个结构?","options":["be + 过去分词","say/tell + that + 从句","will + 动词原形","had + 过去分词"],"answer_index":1,"explanation_cn":"间接引语常用 say/tell + that + 从句 的结构。✓ He told me that…"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp1','choice','{"stem":"\"He said ___ business was bad.\"(引出转述的内容)","options":["that","who","which","what"],"answer_index":0,"stem_cn":"他说生意很糟糕。","explanation_cn":"转述的内容用 that 引出(that 常可省略)。✓ He said that business was bad."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp2','choice','{"stem":"关于 say 和 tell,正确的是:","options":["两个都必须接人","say 后必须接人,tell 后不接人","say 后不接人,tell 后必须接人","两个都不接人"],"answer_index":2,"explanation_cn":"say 后面不直接接人(He said that…);tell 后面必须接人(He told me that…)。✓"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp2','choice','{"stem":"\"他告诉我他很忙\"用哪个动词?","options":["He told that he was busy.","He said me that he was busy.","He say me that he was busy.","He told me that he was busy."],"answer_index":3,"explanation_cn":"\"告诉我\"要用 tell + 人:He told me;said 后不能直接接 me。✓ He told me that he was busy."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp3','choice','{"stem":"转述过去说的话,从句里的时态要怎么变?","options":["往将来走一步","往过去退一步(am→was, will→would)","都改成现在时","保持不变"],"answer_index":1,"explanation_cn":"转述过去说过的话时,从句里的时态往过去\"退一步\":am→was, do→did, will→would, can→could。✓\r\n📌 如果所述的事现在仍然成立,美国人口语里也常不退,直接说 \"She said she''s coming\"(她说她要来,人还没到);考试和正式写作按规范退成 \"She said she was coming\"。两种都对,场合不同。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp3','choice','{"stem":"\"''I am busy,'' he said.\" 改成间接引语:","options":["He said that he be busy.","He said that he will busy.","He said that he is busy.","He said that he was busy."],"answer_index":3,"explanation_cn":"原话 I am busy 转述时,am 往过去退成 was。✓ He said that he was busy."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp3','choice','{"stem":"\"''I will see you,'' she said.\" 里的 will 转述时变成:","options":["would","will","was","shall"],"answer_index":0,"explanation_cn":"原话里的 will,转述过去说的话时变成 would。✓ She said she would see me."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp4','choice','{"stem":"\"''I broke the plate,'' he said.\" 改成间接引语(broke 往过去退一步):","options":["He said that he will break the plate.","He said that he broke the plate now.","He said that he had broken the plate.","He said that he breaks the plate."],"answer_index":2,"explanation_cn":"原话 I broke the plate 转述时,broke 往过去退成 had broken(过去完成)。✓"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp4','choice','{"stem":"\"''I have just finished,'' he said.\" 改成间接引语(have done 往过去退):","options":["He said that he has just finished.","He said that he just finish.","He said that he will just finish.","He said that he had just finished."],"answer_index":3,"explanation_cn":"原话 I have just finished 转述时,have finished 往过去退成 had finished。✓"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp5','choice','{"stem":"\"I don''t know ___ he will come.\"(表示''是否'',后面无 or not)","options":["只能用 that","if 或 whether 都行","只能用 what","只能用 which"],"answer_index":1,"stem_cn":"我不知道他是否会来。","explanation_cn":"表示\"是否\",引出转述内容时 if 或 whether 都可以(后面不紧跟 or not 时)。✓ I don''t know if/whether he will come."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp5','choice','{"stem":"\"I don''t know ___ or not he comes.\"(紧跟 or not,只能用):","options":["what","that","whether","if"],"answer_index":2,"stem_cn":"我不知道他到底来不来。","explanation_cn":"if 不能紧跟 or not(不说 if or not);紧跟 or not 只能用 whether。✓ I don''t know whether or not he comes."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp6','choice','{"stem":"\"He said he ___ go to the north for vacation.\"(从过去看将来,过去将来时)","options":["shall","will","is","would"],"answer_index":3,"stem_cn":"他说他要去北方度假。","explanation_cn":"\"从过去看将来\"用过去将来时 would + 动词原形。✓ He said he would go to the north."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp6','choice','{"stem":"过去将来时怎么构成?","options":["will + 动词原形","would/should + 动词原形","was + 现在分词","had + 过去分词"],"answer_index":1,"explanation_cn":"过去将来时 = would/should + 动词原形(would 通用于各人称)。✓ He said he would go."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp7','choice','{"stem":"\"''I broke my cup,'' Tom said.\" 转述时 I 和 my 变成:","options":["I 和 my","she 和 her","he 和 his","you 和 your"],"answer_index":2,"explanation_cn":"转述别人的话时,人称跟着变:原话的 I→he,my→his。✓ ''I broke my cup.'' → He said he had broken his cup."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp8','choice','{"stem":"转述一般疑问句 \"''Are you busy?'' he asked.\" 用:","options":["He asked are you busy.","He asked if I was busy.","He asked if was I busy?","He asked that I was busy."],"answer_index":1,"explanation_cn":"转述一般疑问句用 ask if/whether + 陈述语序(主语在前,不倒装,不加问号)。✓ He asked if I was busy."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp8','choice','{"stem":"转述疑问句时,从句要用什么语序?","options":["陈述语序(主语在前,不倒装,不加问号)","疑问语序(把 be/助动词提前)","感叹语序","命令语序"],"answer_index":0,"explanation_cn":"转述疑问句时,从句要用陈述语序:主语在前,不把 be/助动词提前,句末不加问号。✓"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',5,'am2_l15_gp7','choice','{"stem":"\"''You can go now,'' the teacher said.\" 转述(时态和人称都要变):","options":["The teacher said that I can go now.","The teacher said that you could went.","The teacher said that I could go then.","The teacher said that you can go now."],"answer_index":2,"explanation_cn":"原话 You can go now 转述时:can→could,you→I(说话对象),now→then。✓ The teacher said that I could go then."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',6,NULL,'choice','{"stem":"美语里\"加薪\"用:","options":["a money add","a pay rise","a pay up","a raise"],"answer_index":3,"explanation_cn":"美语\"加薪\"用 a raise;英式用 a pay rise。✓ I got a raise."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',6,NULL,'choice','{"stem":"美语版把\"an extra thousand pounds\"里的货币换成:","options":["coins","pounds","dollars","cents"],"answer_index":2,"explanation_cn":"美国用美元 dollars 结算;英式原文里的 pounds(英镑),美语版改成 dollars。✓ an extra thousand dollars."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',6,NULL,'choice','{"stem":"美语里\"电梯\"用:","options":["elevator","stair car","up-stair","lift"],"answer_index":0,"explanation_cn":"美语\"电梯\"用 elevator;英式用 lift。✓ I took the elevator up."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',6,NULL,'choice','{"stem":"look up 的意思是:","options":["低头看","抬头看","查字典找不到","放弃"],"answer_index":1,"explanation_cn":"look up = 抬头看。✓ He did not look up from his desk.\r\n顺带记:低头看 = look down;查阅(单词) = look up / check;放弃 = give up."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',6,NULL,'choice','{"stem":"afford to 的意思是:","options":["负担得起(做某事)","忘记做","打算做","拒绝做"],"answer_index":0,"explanation_cn":"afford to = 负担得起做某事,常和 can/could 连用。✓ could not afford to pay.\r\n顺带记:拒绝做 = refuse to do;忘记做 = forget to do;打算做 = plan to do."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',6,NULL,'choice','{"stem":"in a weak voice 的意思是:","options":["用生气的语气","小声偷笑","大声地","用微弱的声音"],"answer_index":3,"explanation_cn":"in a weak voice = 用微弱的声音、有气无力地。✓ I said in a weak voice.\r\n顺带记:大声地 = in a loud voice / loudly;用生气的语气 = in an angry voice;小声偷笑 = giggle quietly."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',7,NULL,'cloze','{"stem":"第 1 空","context":"The secretary told me that Mr. Harrison ___1___ see me. He said that business ___2___ very bad and the firm ___3___ not afford high salaries. I knew that my turn ___4___ come.","blank_no":1,"options":["would","will","shall","is"],"answer_index":0,"explanation_cn":"转述过去说的话,will→would。✓ told me that Mr. Harrison would see me.\r\n✗ will:转述过去说的话,will 要后移成 would;✗ shall:同理不用 shall,转述统一用 would;✗ is:is see 不通,这里需要情态动词 would."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',7,NULL,'cloze','{"stem":"第 2 空","context":"The secretary told me that Mr. Harrison ___1___ see me. He said that business ___2___ very bad and the firm ___3___ not afford high salaries. I knew that my turn ___4___ come.","blank_no":2,"options":["was","is","will be","has been"],"answer_index":0,"explanation_cn":"转述过去说的话,is→was。✓ He said that business was very bad.\r\n✗ is:转述过去说的话,is 要后移成 was;✗ will be:这不是将来,是转述当时的状况;✗ has been:时态后移不用现在完成."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',7,NULL,'cloze','{"stem":"第 3 空","context":"The secretary told me that Mr. Harrison ___1___ see me. He said that business ___2___ very bad and the firm ___3___ not afford high salaries. I knew that my turn ___4___ come.","blank_no":3,"options":["could","can","will","may"],"answer_index":0,"explanation_cn":"转述过去说的话,can→could。✓ the firm could not afford high salaries.\r\n✗ can:转述过去,can 要后移成 could;✗ will:意思不对,不是将来;✗ may:时态和语气都不合,应是 could."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',7,NULL,'cloze','{"stem":"第 4 空","context":"The secretary told me that Mr. Harrison ___1___ see me. He said that business ___2___ very bad and the firm ___3___ not afford high salaries. I knew that my turn ___4___ come.","blank_no":4,"options":["had","has","have","will"],"answer_index":0,"explanation_cn":"\"该轮到我了\"发生在\"我知道\"之前,用过去完成 had come。✓ I knew that my turn had come.\r\n✗ has:\"该轮到我\"在\"我知道\"之前,过去的过去用 had come,不用 has;✗ have:主语 my turn 是单数且要过去完成 had;✗ will:不是将来,是更早发生的事."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',8,NULL,'choice','{"stem":"Who wanted to see the writer?","options":["A coworker","The secretary","Mr. Harrison, the boss","A customer"],"answer_index":2,"explanation_cn":"课文说 The secretary told me that Mr. Harrison would see me,老板哈里森要见作者。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',8,NULL,'choice','{"stem":"What did the boss say about business?","options":["It was closing down","It was growing fast","It was very good","It was very bad"],"answer_index":3,"explanation_cn":"课文说 he said that business was very bad,老板说生意非常差。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',8,NULL,'choice','{"stem":"What was the good news at the end?","options":["The writer would get a raise","The firm was sold","Everyone got a holiday","The writer was fired"],"answer_index":0,"explanation_cn":"课文结尾老板笑着说给作者加薪,这才是好消息。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',9,NULL,'choice','{"stem":"你想转述\"汤姆说他很累\"(转述过去说的话,时态后移):","options":["Tom said me that he tired.","Tom said that he is tired.","Tom said that he was tired.","Tom say that he was tired."],"answer_index":2,"explanation_cn":"转述汤姆说的话:tired 前的 is/am 往过去退成 was。✓ Tom said that he was tired. 场合:把别人说的话讲给第三个人听。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',9,NULL,'choice','{"stem":"你想转述\"她告诉我她会来\"(时态后移,tell 后面接人):","options":["She told that she would come.","She said me that she will come.","She told me that she will come.","She told me that she would come."],"answer_index":3,"explanation_cn":"\"告诉我\"用 tell + 人;will 往过去退成 would。✓ She told me that she would come."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',9,NULL,'choice','{"stem":"你想转述别人问的\"你饿吗?\"(转述一般疑问句,注意语序):","options":["He asked that I was hungry.","He asked if I was hungry.","He asked if was I hungry.","He asked was I hungry."],"answer_index":1,"explanation_cn":"转述一般疑问句\"你饿吗\"用 ask if + 陈述语序(不倒装、不加问号)。✓ He asked if I was hungry."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',10,NULL,'choice','{"stem":"nervous 的意思是:","options":["开心的","紧张的","困倦的","生气的"],"answer_index":1,"explanation_cn":"nervous = 紧张的。✓ I felt very nervous.\r\n顺带记:生气的 = angry;开心的 = happy;困倦的 = sleepy."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',10,NULL,'choice','{"stem":"afford 的意思是:","options":["打断","收到","拒绝","负担得起"],"answer_index":3,"explanation_cn":"afford = 负担得起。✓ could not afford to pay.\r\n顺带记:打断 = interrupt;收到 = receive;拒绝 = refuse."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',10,NULL,'choice','{"stem":"\"He said that he ___ busy that day.\"(转述过去,is 要变成什么)","options":["will be","is","was","has been"],"answer_index":2,"stem_cn":"他说他那天很忙。","explanation_cn":"转述过去说的话,is→was。✓ He said that he was busy that day."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',10,NULL,'choice','{"stem":"\"She told me that she ___ finished the work.\"(have finished 要变成什么)","options":["has","have","will have","had"],"answer_index":3,"stem_cn":"她告诉我她已经完成了那项工作。","explanation_cn":"转述里 have finished 往过去退成 had finished。✓ She told me that she had finished the work."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',10,NULL,'choice','{"stem":"\"He told me that he would call.\" 意思是:","options":["他正在打电话","他问我是否会打电话","他告诉我他会打电话","他让我打电话"],"answer_index":2,"explanation_cn":"He told me that he would call = 他告诉我他会打电话(转述别人说的话,will→would)。✓"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',10,NULL,'choice','{"stem":"转述\"她说''我明天来''\",下面对的是:","options":["She said me she comes tomorrow.","She told that she come the next day.","She said that she will come tomorrow.","She said that she would come the next day."],"answer_index":3,"explanation_cn":"转述\"我明天来\"时:will→would,tomorrow→the next day。✓ She said that she would come the next day."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',10,NULL,'choice','{"stem":"Why did the writer feel nervous at first?","options":["He did not know the boss","He had lost some money","He thought he was about to be fired","He was late for work"],"answer_index":2,"passage":"The secretary told me that Mr. Harrison would see me right away. I felt very nervous as I took the elevator up to his office. He did not even look up from his desk when I walked in. After I had sat down, he said that business was very bad. He told me that the firm could not afford to pay such high salaries. Twenty people had already been let go, and I knew that my turn had come. \"Mr. Harrison,\" I said in a weak voice, \"may I say something?\" \"Don''t interrupt me,\" he said sharply. Then he suddenly smiled and told me that I would get a raise. He said I would receive an extra thousand dollars a year. It was the best news I had heard all year!","explanation_cn":"课文说作者进办公室很紧张,以为公司裁人这回该轮到自己被辞退了。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',10,NULL,'choice','{"stem":"How did the meeting actually turn out?","options":["The boss gave him a raise instead of firing him","The boss closed the office","The boss fired him","The boss asked him to leave the firm"],"answer_index":0,"passage":"The secretary told me that Mr. Harrison would see me right away. I felt very nervous as I took the elevator up to his office. He did not even look up from his desk when I walked in. After I had sat down, he said that business was very bad. He told me that the firm could not afford to pay such high salaries. Twenty people had already been let go, and I knew that my turn had come. \"Mr. Harrison,\" I said in a weak voice, \"may I say something?\" \"Don''t interrupt me,\" he said sharply. Then he suddenly smiled and told me that I would get a raise. He said I would receive an extra thousand dollars a year. It was the best news I had heard all year!","explanation_cn":"课文结尾老板不但没裁他,反而给他加薪一千,结果出人意料。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',10,NULL,'choice','{"stem":"How did the writer feel when he walked into the office?","options":["Very happy","Very nervous","Very sleepy","Very angry"],"answer_index":1,"audio":"The secretary told me that Mr. Harrison would see me right away. I felt very nervous as I took the elevator up to his office. He did not even look up from his desk when I walked in. After I had sat down, he said that business was very bad. He told me that the firm could not afford to pay such high salaries. Twenty people had already been let go, and I knew that my turn had come. \"Mr. Harrison,\" I said in a weak voice, \"may I say something?\" \"Don''t interrupt me,\" he said sharply. Then he suddenly smiled and told me that I would get a raise. He said I would receive an extra thousand dollars a year. It was the best news I had heard all year!","explanation_cn":"课文说 I felt very nervous when I walked in,作者进办公室时非常紧张。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l15',10,NULL,'choice','{"stem":"How much extra money would the writer get a year?","options":["Nothing","Ten dollars","A hundred dollars","A thousand dollars"],"answer_index":3,"audio":"The secretary told me that Mr. Harrison would see me right away. I felt very nervous as I took the elevator up to his office. He did not even look up from his desk when I walked in. After I had sat down, he said that business was very bad. He told me that the firm could not afford to pay such high salaries. Twenty people had already been let go, and I knew that my turn had come. \"Mr. Harrison,\" I said in a weak voice, \"may I say something?\" \"Don''t interrupt me,\" he said sharply. Then he suddenly smiled and told me that I would get a raise. He said I would receive an extra thousand dollars a year. It was the best news I had heard all year!","explanation_cn":"课文说 I would receive an extra thousand dollars a year,每年多拿一千美元。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l16',2,2,16,'A polite request','彬彬有礼的要求','if 条件句(主考:第一类真实条件 if + 一般现在时,主句 will/won''t/祈使句/can · 前置后置 · 从句用现在时不用 will)+ 主谓一致(辅考:集合名词 police/family 用复数 · 就近/就前 as well as/neither nor)','停错车通常会被警察贴罚单 · 但在瑞典度假时车上发现一张客气的便条——欢迎光临本市、此处禁停、请留意路牌、这只是提醒','{"q":"Listen and answer — What was the polite request?","options":["A friendly note asking the driver to obey the No Parking signs","A parking ticket","An invitation to a party","A traffic fine notice"],"answer_index":0}'::jsonb,'{"title":"说\"如果…就…\"(if 条件句)","intro":"本课讲怎么说\"如果满足某个条件,将来就会怎样\"——if 条件句。注意:if 后面那半句用一般现在时,后半句才用将来时(will)。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["if + 一般现在时,另一半用将来时 will","If you park here, a police officer will find it."],["if 那半句(说条件)用现在时,不用 will","If it rains tomorrow(不是 will rain), we will stay home."],["if 这半句可以放句首(加逗号)也可以放句尾","If you hurry, you''ll catch it. = You''ll catch it if you hurry."],["后半句也可以是 won''t / 祈使句 / can","If you make a mistake, correct it. / If he can, he will come."]]},"specialRules":[{"rule":"if 条件疑问:if + 现在时 + 疑问(If you see him, will you tell him?)","mark":"条件疑问"},{"rule":"police(警察)是集合名词,后面的动词用复数:Traffic police are polite(主谓一致)","mark":"police 用复数"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l16',1,NULL,'If you park in the wrong parking lot, a police officer will find your car fast.','要是你把车停错了停车场,警察很快就会找到你的车。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l16',2,NULL,'You will be lucky if the officer lets you off without a ticket.','要是警察没给你开罚单就放你走,算你走运。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l16',3,NULL,'However, that does not always happen.','不过,情况并不总是这样。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l16',4,NULL,'Traffic police are sometimes surprisingly polite.','交通警察有时客气得出人意料。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l16',5,NULL,'On a trip downtown in Sweden, I found this friendly note on my car:','有一次在瑞典市中心闲逛,我发现车上有这样一张友好的便条:') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l16',6,NULL,'"Welcome to our city! This is a No Parking area.','"欢迎光临本市!此处为禁停区。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l16',7,NULL,'You will enjoy your stay here if you pay attention to our street signs.','只要您留意我们的路牌,您在这儿一定会过得愉快。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l16',8,NULL,'We have your license plate, but this note is only a reminder."','我们已记下您的车牌,但这张便条只是善意提醒。"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l16',9,NULL,'If you get a polite note like this, you cannot fail to obey it.','要是你收到这样一张客气的便条,你是不会不照办的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l16',10,NULL,'A kind reminder often works better than an angry ticket.','一句善意的提醒往往比一张冷冰冰的罚单更管用。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l16',11,NULL,'If you ever visit this city, you will surely feel welcome.','要是你哪天来这座城市,你一定会感到宾至如归。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
