INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp1','choice','{"stem":"if 条件句用来说什么?","options":["过去发生的事","此刻正在做的事","如果满足条件,将来就会发生的事","经常反复的习惯"],"answer_index":2,"explanation_cn":"if 条件句用来说\"如果满足某个条件,将来就会怎样\"。✓ If you park here, a police officer will find it."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp1','choice','{"stem":"\"If it ___ tomorrow, we will stay home.\"(rain,if 那半句用现在时)","options":["rains","rained","is raining","will rain"],"answer_index":0,"stem_cn":"如果明天下雨,我们就待在家里。","explanation_cn":"if 那半句(说条件的)用一般现在时,不用 will;rain 加 s → rains。✓ If it rains tomorrow, we will stay home."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp1','choice','{"stem":"\"If you park here, a police officer ___ your car.\"(find,后半句用将来)","options":["found","finds","will find","finding"],"answer_index":2,"stem_cn":"如果你停在这儿,警察会找到你的车。","explanation_cn":"后半句(说结果的)表示将来,用 will + 动词原形 find。✓ a police officer will find your car."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp2','choice','{"stem":"if 那半句(说条件的)可以放在:","options":["句首(后加逗号)或句尾都行","只能放句尾","只能放句首","只能放句子中间"],"answer_index":0,"explanation_cn":"if 那半句可以放句首(后面加逗号),也可以放句尾(不加逗号)。✓ If you hurry, you''ll catch it. = You''ll catch it if you hurry."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp2','choice','{"stem":"下面标点正确的一句是:","options":["You will catch, the bus if you hurry.","If, you hurry you will catch the bus.","If you hurry, you will catch the bus.","If you hurry you will, catch the bus."],"answer_index":2,"explanation_cn":"if 半句在句首时,后面加一个逗号,再接后半句。✓ If you hurry, you will catch the bus."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp3','choice','{"stem":"\"If he is working, I ___ disturb him.\"(后半句:不去打扰)","options":["will","not will","don''t will","won''t"],"answer_index":3,"stem_cn":"如果他在工作,我就不去打扰他。","explanation_cn":"\"我就不去打扰他\"——后半句表示\"将来不会\",用 won''t(will not)。✓ If he is working, I won''t disturb him."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp3','choice','{"stem":"\"If you make a mistake, ___ it.\"(if + 让人做某事:改正它)","options":["will correct","corrected","correct","corrects"],"answer_index":2,"stem_cn":"如果你犯了错,就改正它。","explanation_cn":"后半句也可以是让对方做某事的祈使句,动词用原形 correct。✓ If you make a mistake, correct it."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp4','choice','{"stem":"if 条件句里,表示将来的事,if 那半句里的动词用:","options":["一般现在时(不用 will)","一般过去时","现在完成时","一般将来时 will"],"answer_index":0,"explanation_cn":"if 条件句里,哪怕说的是将来的事,if 那半句也用一般现在时,不用 will。✓ If it rains(不是 will rain)…"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp4','choice','{"stem":"选出正确的一句:","options":["If it will rains, we stay home.","If it rains, we will stay home.","If it will rain, we will stay home.","If it rain, we will stayed home."],"answer_index":1,"explanation_cn":"if 半句用一般现在时 rains,后半句用 will stay。其它三句都把 will 放错了地方或动词形式不对。✓"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp5','choice','{"stem":"\"If you see him, ___ you tell him about it?\"(if + 疑问)","options":["are","do","will","did"],"answer_index":2,"stem_cn":"如果你见到他,你会告诉他这件事吗?","explanation_cn":"\"如果你见到他,你能告诉他吗\"——if + 现在时,后半句是将来的疑问,用 will 提前。✓ If you see him, will you tell him?"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp6','choice','{"stem":"\"You ___ the train if you don''t hurry.\"(miss,后半句将来)","options":["are missing","miss","missed","will miss"],"answer_index":3,"stem_cn":"如果你不快点,就会错过火车。","explanation_cn":"\"你会误了火车\"是将来的结果,用 will miss。✓ You will miss the train if you don''t hurry."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp6','choice','{"stem":"\"If they can help you, they ___.\"(条件成立,主句表将来)","options":["will","do","are","can to"],"answer_index":0,"stem_cn":"如果他们能帮你,他们会帮的。","explanation_cn":"\"他们会帮你的\"——后半句省略了动词,只用 will 结尾。✓ If they can help you, they will."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp7','choice','{"stem":"police(警察)这个词,后面的动词一般用:","options":["不定式","复数动词(are/were)","单数动词(is/was)","过去分词"],"answer_index":1,"explanation_cn":"police(警察)是集合名词,指一群人,后面的动词用复数(are/were)。✓ Traffic police are polite."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp7','choice','{"stem":"\"Traffic police ___ sometimes very polite.\"(police 用复数)","options":["am","was","are","is"],"answer_index":2,"stem_cn":"交通警察有时非常客气。","explanation_cn":"police 后面的动词用复数 are。✓ Traffic police are sometimes very polite."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp7','choice','{"stem":"\"My family ___ all early risers.\"(把家人看成一个个成员,用复数)","options":["are","is","was","am"],"answer_index":0,"stem_cn":"我家人都是早起的人。","explanation_cn":"把 family(家人)看成一个个成员时,后面的动词用复数 are。✓ My family are all early risers."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp8','choice','{"stem":"\"The father as well as his children ___ here.\"(as well as 跟前面的 father)","options":["are","am","were","is"],"answer_index":3,"stem_cn":"父亲和他的孩子们都在这儿。","explanation_cn":"as well as 连接两个名词时,动词跟前面那个(the father),father 是单数,用 is。✓ The father as well as his children is here."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp8','choice','{"stem":"as well as / with / along with 连接两个名词作起点时,动词跟:","options":["前面那个词(就前一致)","两个一起","永远用复数","后面那个词"],"answer_index":0,"explanation_cn":"as well as / with / along with 连接名词作起点时,动词跟前面那个词(就前一致),不受后面词影响。✓"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',5,'am2_l16_gp8','choice','{"stem":"\"Neither you nor he ___ right.\"(neither…nor 跟离得近的 he)","options":["are","were","am","is"],"answer_index":3,"stem_cn":"你和他都不对。","explanation_cn":"neither…nor 连接两个词时,动词跟离得近的那个(he),he 用 is。✓ Neither you nor he is right."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',6,NULL,'choice','{"stem":"美语\"停车场\"用:","options":["stop place","park zone","car park","parking lot"],"answer_index":3,"explanation_cn":"美语\"停车场\"用 parking lot;英式用 car park。✓ park in the parking lot."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',6,NULL,'choice','{"stem":"美语\"市中心\"用:","options":["city centre","town heart","downtown","mid city"],"answer_index":2,"explanation_cn":"美语\"市中心\"用 downtown;英式用 city centre。✓ a trip downtown."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',6,NULL,'choice','{"stem":"美语\"车牌\"用:","options":["license plate","car number","number plate","plate card"],"answer_index":0,"explanation_cn":"美语\"车牌\"用 license plate;英式用 number plate。✓ We have your license plate."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',6,NULL,'choice','{"stem":"pay attention to 的意思是:","options":["指出","注意,留意","付钱给","忽视"],"answer_index":1,"explanation_cn":"pay attention to = 注意、留意。✓ Pay attention to our street signs.\r\n顺带记:付钱给 = pay (for);忽视 = ignore;指出 = point out."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',6,NULL,'choice','{"stem":"fail to 的意思是:","options":["未能 / 没做到","拒绝做","打算做","成功做到"],"answer_index":0,"explanation_cn":"fail to = 未能、没做到;cannot fail to = 一定会(双重否定)。✓ You cannot fail to obey it.\r\n顺带记:成功做到 = succeed in / manage to;打算做 = plan to do;拒绝做 = refuse to do."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',6,NULL,'choice','{"stem":"welcome to 的意思是:","options":["拒绝进入","欢迎来到","欢送","告别"],"answer_index":1,"explanation_cn":"welcome to = 欢迎来到(某地)。✓ Welcome to our city!\r\n顺带记:告别 = say goodbye to;欢送 = see off;拒绝进入 = refuse entry / keep out."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',7,NULL,'cloze','{"stem":"第 1 空","context":"If you ___1___ in the wrong spot, a police officer ___2___ your car. You will enjoy your stay if you ___3___ attention to the signs. If you ___4___ a polite note, you cannot fail to obey it.","blank_no":1,"options":["park","will park","parked","are parking"],"answer_index":0,"explanation_cn":"if 那半句用一般现在时 park。✓ If you park in the wrong spot…\r\n✗ will park:if 那半句用一般现在时,不用 will;✗ parked:说的是将来可能发生的条件,不是过去;✗ are parking:if 从句一般不用现在进行,用一般现在 park."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',7,NULL,'cloze','{"stem":"第 2 空","context":"If you ___1___ in the wrong spot, a police officer ___2___ your car. You will enjoy your stay if you ___3___ attention to the signs. If you ___4___ a polite note, you cannot fail to obey it.","blank_no":2,"options":["will find","finds","found","find"],"answer_index":0,"explanation_cn":"后半句表将来,用 will find。✓ a police officer will find your car.\r\n✗ finds:主句说将来的结果,用 will find;✗ found:不是过去发生的事;✗ find:主句结果要加 will,不能光用原形."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',7,NULL,'cloze','{"stem":"第 3 空","context":"If you ___1___ in the wrong spot, a police officer ___2___ your car. You will enjoy your stay if you ___3___ attention to the signs. If you ___4___ a polite note, you cannot fail to obey it.","blank_no":3,"options":["pay","will pay","paid","paying"],"answer_index":0,"explanation_cn":"if 半句用一般现在时 pay。✓ if you pay attention to the signs.\r\n✗ will pay:if 那半句用一般现在时,不用 will;✗ paid:不是过去;✗ paying:缺助动词,单独 paying 不能作谓语."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',7,NULL,'cloze','{"stem":"第 4 空","context":"If you ___1___ in the wrong spot, a police officer ___2___ your car. You will enjoy your stay if you ___3___ attention to the signs. If you ___4___ a polite note, you cannot fail to obey it.","blank_no":4,"options":["get","will get","got","getting"],"answer_index":0,"explanation_cn":"if 半句用一般现在时 get。✓ If you get a polite note…\r\n✗ will get:if 那半句用一般现在时,不用 will;✗ got:不是过去;✗ getting:缺助动词,单独 getting 不能作谓语."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',8,NULL,'choice','{"stem":"What happens if you park in the wrong place?","options":["You get a prize","A police officer will find your car","Nothing ever happens","The car disappears"],"answer_index":1,"explanation_cn":"课文说 If you park in the wrong place, a police officer will find your car,停错地方警察会找到车。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',8,NULL,'choice','{"stem":"What did the writer find on the car in Sweden?","options":["A flower","A parking ticket","A polite note","A map"],"answer_index":2,"explanation_cn":"课文说 I found this friendly note on my car,作者在车上发现一张客气的便条。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',8,NULL,'choice','{"stem":"Was the note a fine or just a reminder?","options":["Only a reminder","A big fine","A bill","A court order"],"answer_index":0,"explanation_cn":"课文说 this note is only a reminder,那张便条只是善意提醒,不是罚单。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',9,NULL,'choice','{"stem":"你想说\"如果明天下雨,我就待在家\"(if 条件表将来):","options":["If it will rain tomorrow, I stay home.","If it rained tomorrow, I will stay home.","If it rains tomorrow, I stayed home.","If it rains tomorrow, I will stay home."],"answer_index":3,"explanation_cn":"if 半句用一般现在时 rains,后半句用 will stay。✓ 场合:说自己下雨天的打算。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',9,NULL,'choice','{"stem":"你想说\"如果你饿了,就吃点东西\"(if + 让对方做某事):","options":["If you are hungry, eat something.","If you hungry, ate something.","If you will be hungry, eat something.","If you are hungry, you eating something."],"answer_index":0,"explanation_cn":"if 半句用一般现在时 are;后半句让对方做某事,用原形 eat。✓ 场合:招呼客人别客气。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',9,NULL,'choice','{"stem":"你想说\"警察正在维持秩序\"(police 用复数动词):","options":["The police is keeping order.","The police are keeping order.","The police am keeping order.","The police keeps order now."],"answer_index":1,"explanation_cn":"police 后面的动词用复数 are。✓ The police are keeping order. 场合:描述警察正在做什么。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',10,NULL,'choice','{"stem":"obey 的意思是:","options":["服从,遵守","拒绝","忘记","停车"],"answer_index":0,"explanation_cn":"obey = 服从、遵守。✓ you cannot fail to obey it.\r\n顺带记:拒绝 = refuse;忘记 = forget;停车 = park."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',10,NULL,'choice','{"stem":"reminder 的意思是:","options":["罚款单","地图","车牌","提示,提醒"],"answer_index":3,"explanation_cn":"reminder = 提示、提醒。✓ this note is only a reminder.\r\n顺带记:罚款单 = ticket / fine;车牌 = license plate;地图 = map."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',10,NULL,'choice','{"stem":"\"If you ___ hard, you will pass the test.\"(if 那半句用一般现在时,不用将来时)","options":["working","work","worked","will work"],"answer_index":1,"stem_cn":"如果你努力学习,就会通过考试。","explanation_cn":"if 那半句用一般现在时 work。✓ If you work hard, you will pass the test."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',10,NULL,'choice','{"stem":"\"If he plays well, he ___ into the team.\"(get,后半句用将来)","options":["will get","got","gets","getting"],"answer_index":0,"stem_cn":"如果他表现出色,就会入选球队。","explanation_cn":"后半句表将来,用 will get。✓ If he plays well, he will get into the team."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',10,NULL,'choice','{"stem":"\"If you don''t like it, don''t buy it.\" 这句话的意思是:","options":["你不喜欢也得买","如果你不喜欢,就别买","你买了就会喜欢","别人不喜欢你就别买"],"answer_index":1,"explanation_cn":"If you don''t like it, don''t buy it. = 如果你不喜欢,就别买它(前半句说条件,后半句让对方别做)。✓"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',10,NULL,'choice','{"stem":"\"The police ___ looking for the thief.\" 横线填(police 用复数):","options":["am","was","is","are"],"answer_index":3,"stem_cn":"警察正在搜捕小偷。","explanation_cn":"police 后面的动词用复数,填 are。✓ The police are looking for the thief."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',10,NULL,'choice','{"stem":"Why do people usually get a ticket?","options":["Because they visit Sweden","Because they are polite","Because they park in the wrong place","Because they drive too slowly"],"answer_index":2,"passage":"If you park in the wrong parking lot, a police officer will find your car fast. You will be lucky if the officer lets you off without a ticket. However, that does not always happen. Traffic police are sometimes surprisingly polite. On a trip downtown in Sweden, I found this friendly note on my car: \"Welcome to our city! This is a No Parking area. You will enjoy your stay here if you pay attention to our street signs. We have your license plate, but this note is only a reminder.\" If you get a polite note like this, you cannot fail to obey it. A kind reminder often works better than an angry ticket. If you ever visit this city, you will surely feel welcome.","explanation_cn":"课文说 If you park in the wrong place, a police officer will find it,停错地方才会被开罚单。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',10,NULL,'choice','{"stem":"How was the note in Sweden different from a normal ticket?","options":["It was polite and only a reminder, not a fine","It was a court summons","It was much bigger","It was written in French"],"answer_index":0,"passage":"If you park in the wrong parking lot, a police officer will find your car fast. You will be lucky if the officer lets you off without a ticket. However, that does not always happen. Traffic police are sometimes surprisingly polite. On a trip downtown in Sweden, I found this friendly note on my car: \"Welcome to our city! This is a No Parking area. You will enjoy your stay here if you pay attention to our street signs. We have your license plate, but this note is only a reminder.\" If you get a polite note like this, you cannot fail to obey it. A kind reminder often works better than an angry ticket. If you ever visit this city, you will surely feel welcome.","explanation_cn":"课文说瑞典那张便条很客气、只是提醒,和普通冷冰冰的罚单不一样。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',10,NULL,'choice','{"stem":"Where did the writer get the polite note?","options":["At home","In Sweden, on a trip downtown","At the airport","In a garage in France"],"answer_index":1,"audio":"If you park in the wrong parking lot, a police officer will find your car fast. You will be lucky if the officer lets you off without a ticket. However, that does not always happen. Traffic police are sometimes surprisingly polite. On a trip downtown in Sweden, I found this friendly note on my car: \"Welcome to our city! This is a No Parking area. You will enjoy your stay here if you pay attention to our street signs. We have your license plate, but this note is only a reminder.\" If you get a polite note like this, you cannot fail to obey it. A kind reminder often works better than an angry ticket. If you ever visit this city, you will surely feel welcome.","explanation_cn":"课文说 On a trip downtown in Sweden, I found this note,作者在瑞典市中心闲逛时发现的。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l16',10,NULL,'choice','{"stem":"What did the note ask the driver to do?","options":["Leave the city at once","Move to another hotel","Pay attention to the street signs","Pay a big fine"],"answer_index":2,"audio":"If you park in the wrong parking lot, a police officer will find your car fast. You will be lucky if the officer lets you off without a ticket. However, that does not always happen. Traffic police are sometimes surprisingly polite. On a trip downtown in Sweden, I found this friendly note on my car: \"Welcome to our city! This is a No Parking area. You will enjoy your stay here if you pay attention to our street signs. We have your license plate, but this note is only a reminder.\" If you get a polite note like this, you cannot fail to obey it. A kind reminder often works better than an angry ticket. If you ever visit this city, you will surely feel welcome.","explanation_cn":"便条说 You will enjoy your stay here if you pay attention to our street signs,请司机留意路牌。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
